insert into public.questions (id,course_id,paper_code,stem,option_a,option_b,option_c,option_d,official_answer,verified_answer) values ('geological-assistant-pp-q003','geological-assistant','Kerala PSC Assistant Geologist 2025','Which property is the main control on whether one ion can replace another in a mineral?','Similar ionic radius','Equal atomic mass','Same crystal colour','Same melting point of the metal','a','a') on conflict (id) do update set stem=excluded.stem,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,official_answer=excluded.official_answer,verified_answer=excluded.verified_answer;
